cypress_script:
describe('Select Menu Widget Tests', () => {
  it('should select a car successfully', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('select#cars').select('Volvo');
    cy.get('select#cars').should('have.value', 'volvo');
  });
  it('should not navigate away when no selection is made', () => {
    cy.visit('https://demoqa.com/select-menu');
    cy.get('select#cars').select('');
    cy.url().should('eq', 'https://demoqa.com/select-menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Select Menu Widget Tests', () => {
  test('should select a car successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('select#cars', 'volvo');
    const selectedValue = await page.$eval('select#cars', el => el.value);
    expect(selectedValue).toBe('volvo');
  });
  test('should not navigate away when no selection is made', async ({ page }) => {
    await page.goto('https://demoqa.com/select-menu');
    await page.selectOption('select#cars', '');
    expect(page.url()).toBe('https://demoqa.com/select-menu');
  });
});
